// AiXenix Cosmos Lab: regions of the Universe map (content-owned, additive navigation metadata).
//
// A region is either a physical association (the Local Group and its subgroups, galaxy groups, galaxy clusters) or a named
// navigation region (galaxies that are near each other on the sky / in space, with no physical claim). `association` says
// which, and `associationNote` says exactly what is and is not claimed. Regions are not model inputs: they never change a
// galaxy record, a model star or an address. No group or cluster dynamics are simulated.
//
// Hierarchy: the implicit root "Nearby universe" > top-level regions (parent null) > subgroups (parent = region id).
// Every galaxy has exactly one primary (innermost) region: PRIMARY_REGION / regionOf().
//
// Data: generated by web/docs/cosmos/build_cosmos_data.py from web/docs/cosmos/regions.py (membership from the cited group
// and cluster catalogues). Derived geometry (centroidPc, extentPc, distanceRangeKpc) uses the galaxies' galactocentricPc.

import type { Lang, LocalizedText } from './catalog';
import { tx } from './catalog';
import type { Measured, Vec3 } from './cosmos';
import { COSMOS_REGIONS, PRIMARY_REGION } from './cosmos-regions.generated';

export { COSMOS_REGIONS, PRIMARY_REGION };

export type RegionKind = 'group' | 'subgroup' | 'cluster' | 'navigation_region';
export type RegionAssociation = 'gravitationally_bound' | 'probable_group' | 'loose_or_uncertain' | 'sky_region_only';

export interface CosmosRegion {
  id: string; // [a-z0-9_]+ — never equal to a galaxy id
  name: LocalizedText;
  kind: RegionKind;
  kindLabel: LocalizedText;
  association: RegionAssociation;
  /** What is and is not claimed physically (e.g. "the Fornax Cluster, not the Milky Way's Fornax dwarf"). */
  associationNote: LocalizedText;
  /** Enclosing region id; null for top-level regions (their parent is the implicit "Nearby universe"). */
  parent: string | null;
  /** Child region ids (subgroups). */
  children: string[];
  /** The dominant or central galaxy, used for the card distance; null for a navigation list. */
  anchorGalaxy: string | null;
  description: LocalizedText;
  /** Galaxies whose primary region is this one. */
  directMembers: string[];
  /** All galaxies in the region, including those of child regions. */
  members: string[];
  memberCount: number;
  /** Mean galactocentric position of all members (pc). */
  centroidPc: Vec3;
  /** Largest member distance from the centroid plus that member's radius (pc, at least 5 kpc): frames the whole region. */
  extentPc: number;
  /** Nearest and farthest member distance from the Sun (kpc; the Milky Way excluded). */
  distanceRangeKpc: [number, number];
  /** The anchor galaxy's distance in Mpc, with its uncertainty (absent for navigation lists). */
  distanceMpc?: Measured;
  /** COSMOS_SOURCES ids (catalogues the membership comes from). */
  sources: string[];
  /** Display order in the places list. */
  order: number;
}

const L = (en: string, ru: string): LocalizedText => ({ en, ru });

const regionIndex = new Map(COSMOS_REGIONS.map((r) => [r.id, r]));

/** Regions in display order. */
export const REGION_ORDER: string[] = [...COSMOS_REGIONS].sort((a, b) => a.order - b.order).map((r) => r.id);

export const NEARBY_UNIVERSE = { id: 'nearby_universe', name: L('Nearby universe', 'Ближняя Вселенная') } as const;

export function regionById(id: string): CosmosRegion | undefined {
  return regionIndex.get(id);
}

/** The galaxy's primary (innermost) region. */
export function regionOf(galaxyId: string): CosmosRegion | undefined {
  const id = PRIMARY_REGION[galaxyId];
  return id ? regionIndex.get(id) : undefined;
}

/** The chain of regions containing a galaxy, innermost first (e.g. mw_subgroup, local_group). */
export function regionPath(galaxyId: string): CosmosRegion[] {
  const out: CosmosRegion[] = [];
  let r = regionOf(galaxyId);
  while (r) {
    out.push(r);
    r = r.parent ? regionIndex.get(r.parent) : undefined;
  }
  return out;
}

/** Top-level regions (directly under "Nearby universe") in display order. */
export function topRegions(): CosmosRegion[] {
  return REGION_ORDER.map((id) => regionIndex.get(id)!).filter((r) => r.parent === null);
}

